class Solution {
public:
    int minimumSubarrayLength(vector<int>& nums, int k) {
        int n = nums.size();
        int ans = INT_MAX;
        vector<pair<int,int>> cur;
        for (int i = 0; i < n; i++) {
            vector<pair<int,int>> nxt;
            nxt.push_back({nums[i], i});
            for (auto& [v, j] : cur) {
                nxt.push_back({v | nums[i], j});
            }
            cur.clear();
            for (auto& [v, j] : nxt) {
                if (!cur.empty() && cur.back().first == v) continue;
                cur.push_back({v, j});
            }
            for (auto& [v, j] : cur) {
                if (v >= k) {
                    ans = min(ans, i - j + 1);
                }
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};
